local config = {
  ui_story_5062_50620101_1_dialog_content = "Bagaimana keadaan di sepanjang jalur transportasi? Apakah tim pengawalan sudah siap?",
  ui_story_5062_50620101_2_dialog_content = "Nyonya, jalur transportasi sudah siap beroperasi, dan tim pengawal baru saja berangkat. Perkiraan waktu kedatangan adalah...",
  ui_story_5062_50620101_3_dialog_content = "Dan ekstraksi sumber daya lokal?",
  ui_story_5062_50620101_4_dialog_content = "Tim ekstraksi sudah merencanakan rute ekstraksi. Batch pertama sumber daya akan diamankan dalam hari ini.",
  ui_story_5062_50620101_5_dialog_content = "Marsekal Agung, pondasi dasar pos luar sudah berhasil dibangun...",
  ui_story_5062_50620101_6_dialog_content = "Namun, kita kekurangan tenaga. Untuk sementara, kita harus menugaskan penjaga sesuai dengan jadwal ini.",
  ui_story_5062_50620101_7_dialog_content = "Dan Eclipsite? Apakah ada yang melihat mereka?",
  ui_story_5062_50620101_8_dialog_content = "Belum saat ini. Untuk saat ini, perimeter Twilight aman.",
  ui_story_5062_50620101_9_dialog_content = "Paham. Ayo kita lanjutkan dan ikuti jadwal ini untuk saat ini.",
  ui_story_5062_50620101_10_dialog_content = "Grand Marshal, berikut adalah daftar permintaan dari berbagai tim rekonstruksi kami.",
  ui_story_5062_50620101_11_dialog_content = "Benda ini berat sekali! Orang-orang yang keras kepala ini benar-benar senang memerintahkan Grand Marshal baru, bukan?",
  ui_story_5062_50620101_12_dialog_content = "Kita sudah kekurangan personel... Jika kita tidak membuat rencana yang masuk akal, kita sulit untuk mendorong pekerjaan rekonstruksi maju.",
  ui_story_5062_50620101_13_dialog_content = "Komandan Wrath?",
  ui_story_5062_50620101_14_dialog_content = "Ah, kau berhasil, PlayerName.",
  ui_story_5062_50620101_15_dialog_content = "Siap, Kapten. PlayerName, melapor untuk bertugas.",
  ui_story_5062_50620101_16_dialog_content = "Ayo... Secara teknis, Twilight bukan termasuk wilayah Illumina, jadi kalian bisa berhenti bersikap formal di sini.",
  ui_story_5062_50620101_17_dialog_content = "Alasan utama aku memanggilmu ke sini adalah karena aku butuh bantuanmu dalam beberapa hal...",
  ui_story_5062_50620101_18_dialog_content = "Seperti yang Anda tahu, pertempuran terakhir di Twilight pada dasarnya telah menghancurkan kota ini.",
  ui_story_5062_50620101_19_dialog_content = "Masalahnya, di atas kertas, sebagian tempat ini sebenarnya berada di bawah yurisdiksi Illumina...",
  ui_story_5062_50620101_20_dialog_content = "Jadi federasi memutuskan untuk meminta kami membantu dalam rekonstruksi Twilight.",
  ui_story_5062_50620101_21_dialog_content = "Kita akan membangun kembali Twilight? Keren!",
  ui_story_5062_50620101_22_dialog_content = "Benar, tapi yang kamu lihat... pekerjaan organisasi seperti ini jauh lebih sulit daripada memimpin pasukan di medan perang, setidaknya bagi saya, bagaimanapun...",
  ui_story_5062_50620101_23_dialog_content = "Tenslotte, ini adalah jenis hal yang biasanya diurus oleh Chief of Staff...",
  ui_story_5062_50620101_24_dialog_content = "Grand Marshal Wrath, kinerja Anda dalam memimpin dan mendistribusikan proyek rekonstruksi ini sangat penting untuk penilaian Anda.",
  ui_story_5062_50620101_25_dialog_content = "Baiklah. Kamu dengar apa yang dia katakan.",
  ui_story_5062_50620101_26_dialog_content = "Penghitungan apa?",
  ui_story_5062_50620101_27_dialog_content = "Aku akan ceritakan nanti... Untuk saat ini, yang ingin aku katakan adalah, aku senang mereka masih mengizinkanku mencari bantuan dari luar. Itu maksudnya kamu, ya.",
  ui_story_5062_50620101_28_dialog_content = "Aku tahu betapa sulitnya mengelola segala sesuatu di atas Colossus dengan begitu banyak orang, jadi aku yakin kamu memang ahli dalam pekerjaan semacam ini.",
  ui_story_5062_50620101_29_dialog_content = "Akan kucoba semampuku untuk membantu!",
  ui_story_5062_50620101_30_dialog_content = "Aku berharap kau akan mengatakan itu.",
  ui_story_5062_50620101_31_dialog_content = "Baiklah. Izinkan saya menjelaskan situasi di sini, PlayerName...",
  ui_story_5062_50620101_32_dialog_content = "Grand Marshal, beberapa penduduk lokal berkumpul di luar.",
  ui_story_5062_50620101_33_dialog_content = "Kepala Staf, bisakah kamu mengurus ini untukku? Aku perlu berbicara dengan PlayerName.",
  ui_story_5062_50620101_34_dialog_content = "Aku mengerti.",
  ui_story_5062_50620101_35_dialog_content = "Baiklah, sekarang langsung ke intinya saja.",
  ui_story_5062_50620101_36_dialog_content = "Perencanaan keseluruhan untuk pekerjaan rekonstruksi telah selesai. Artinya, sekarang kita berada pada tahap eksekusi.",
  ui_story_5062_50620101_37_dialog_content = "Masing-masing komandan Illumina bertanggung jawab atas aspek tertentu dari pekerjaan rekonstruksi.",
  ui_story_5062_50620101_38_dialog_content = "Sekarang, para komandan ini telah mengajukan serangkaian permintaan berdasarkan kemajuan proyek rekonstruksi, dan permintaan-permintaan ini... pada akhirnya, mereka dikirim ke sini untuk kami tangani.",
  ui_story_5062_50620101_39_dialog_content = "Sebagai anggota bangga dari Komisi Rekonstruksi Twilight Kantor Pusat Sementara, ini adalah tugas yang kami ikat dengan sumpah.",
  ui_story_5062_50620101_40_dialog_content = "Jadi pada dasarnya, kita harus menemukan orang yang kompeten untuk menangani semua permintaan mereka.",
  ui_story_5062_50620101_41_dialog_content = "Saya mengerti. Tunggu, apakah kamu bilang permintaan itu diajukan oleh para komandan?",
  ui_story_5062_50620101_42_dialog_content = "Ya. Menyenangkan bekerja bersama orang-orang yang akrab, kan?",
  ui_story_5062_50620101_43_dialog_content = "Tentu... Maksudku, tidak, bukan itu yang saya maksud...",
  ui_story_5062_50620101_44_dialog_content = "Grand Marshal, apakah Anda, Kepala Staf, dan komandan lainnya semua di sini di Twilight?",
  ui_story_5062_50620101_45_dialog_content = "Apakah Anda mengimplikasikan bahwa melibatkan para komandan dan saya dalam rekonstruksi Twilight terlalu berlebihan?",
  ui_story_5062_50620101_46_dialog_content = "Benar.",
  ui_story_5062_50620101_47_dialog_content = "Sayangnya. Tidak ada yang melewati kamu.",
  ui_story_5062_50620101_48_dialog_content = "Bukankah kamu bertanya mengapa? Jika saya tidak salah ingat, Eclipsite benar-benar mengabaikan Twilight waktu itu dan langsung menuju Illumina...",
  ui_story_5062_50620101_49_dialog_content = "Jika semua orang berkumpul di Twilight...",
  ui_story_5062_50620101_50_dialog_content = "Pendapatmu ada benarnya, tetapi ini bukan untuk saya putuskan.",
  ui_story_5062_50620101_51_dialog_content = "Orang-orang penting di balik layar sedang menangani dampak dari keseluruhan masalah Reinhardt saat ini.",
  ui_story_5062_50620101_52_dialog_content = "Sebelum semuanya reda, tikus-tikus lab pemberontak kecil ini harus tetap di lubang yang tenang. Itu saja.",
  ui_story_5062_50620101_53_dialog_content = "Apa?! Itu konyol.",
  ui_story_5062_50620101_54_dialog_content = "Saya juga tidak yakin tentang detailnya. Lagi pula, tikus lab seharusnya tidak tahu terlalu banyak, bukan?",
  ui_story_5062_50620101_55_dialog_content = "Yang aku tahu adalah, selama dia di sana, nasib Illumina tampaknya tidak begitu suram.",
  ui_story_5062_50620101_56_dialog_content = "Grand Marshal Reinhardt!?",
  ui_story_5062_50620101_57_dialog_content = "Ya. Dalam keadaan seperti ini, dia adalah satu-satunya orang yang bisa kita andalkan.",
  ui_story_5062_50620101_58_dialog_content = "Dan selain alasan yang diberikan oleh orang-orang penting itu, aku juga bertanggung jawab karena tidak mampu melindungi tempat ini.",
  ui_story_5062_50620101_59_dialog_content = "Bahkan jika hanya demi penduduk kota di sini, aku berjanji akan menyelesaikan tugas rekonstruksi ini dengan sukses luar biasa!",
  ui_story_5062_50620101_60_dialog_content = "Komandan Wrath...",
  ui_story_5062_50620101_61_dialog_content = "Grand Marshal Wrath, aku kembali.",
  ui_story_5062_50620101_62_dialog_content = "Ah, pas banget! Kami juga baru saja selesai ngobrol. Jadi, tadi itu ngomongin apa sih?",
  ui_story_5062_50620101_63_dialog_content = "Kabar baik. Warga Twilight telah bersedia untuk membantu kita dalam rekonstruksi.",
  ui_story_5062_50620101_64_dialog_content = "Umm. Sepertinya ada banyak dari mereka. Baiklah, kita perlu melakukan apa yang bisa kita lakukan untuk mengucapkan terima kasih atas antusiasme mereka.",
  ui_story_5062_50620101_65_dialog_content = "Aku akan memastikan misiku selesai.",
  ui_story_5062_50620101_66_dialog_content = "Kalau begitu, mari ikut aku. Aku akan memberitahu kamu persis apa yang harus kamu lakukan.",
  ui_story_5062_50620101_67_dialog_content = "Oh ya, Petugas Vivian. Mengenai penilaian yang Anda sebutkan sebelumnya, apakah itu...",
  ui_story_5062_50620101_68_dialog_content = "Oh, itu... Apa yang baru saja dikatakan Grand Marshal kepadamu?",
  ui_story_5062_50620101_69_dialog_content = "Dia baru saja berbagi beberapa... dugaannya mengenai tugas rekonstruksi...",
  ui_story_5062_50620101_70_dialog_content = "Nah, saya bisa konfirmasi bahwa Komite memang mengeluarkan tugas penilaian untuk para komandan dan saya.",
  ui_story_5062_50620101_71_dialog_content = "Tidak, ini lebih seperti pengawasan daripada penilaian.",
  ui_story_5062_50620101_72_dialog_content = "Menarik...",
  ui_story_5062_50620101_73_dialog_content = "Tapi jangan khawatir, saya hanya memiliki niat terbaik terhadap Grand Marshal Wrath.",
  ui_story_5062_50620101_74_dialog_content = "Saya adalah Chief of Staff. Memastikan pekerjaan rekonstruksi berjalan lancar adalah tanggung jawab saya.",
  ui_story_5062_50620101_75_dialog_content = "Dan dari yang saya tahu, kali ini para komandan lainnya sepertinya tidak ingin hanya patuh mengikuti perintah saja.",
  ui_story_5062_50620101_76_dialog_content = "Lalu apa yang mereka lakukan di sini?",
  ui_story_5062_50620101_77_dialog_content = "Nah, para komandan lain sebenarnya sudah menerima Grand Marshal Wrath, berkat kekuatannya.",
  ui_story_5062_50620101_78_dialog_content = "Namun, menjadi Grand Marshal yang layak memerlukan lebih dari kemampuan bertempur.",
  ui_story_5062_50620101_79_dialog_content = "Jadi mereka berencana untuk memanfaatkan kesempatan ini untuk menguji kemampuan kepemimpinan dia, dengan cara mereka sendiri.",
  ui_story_5062_50620101_80_dialog_content = "Tapi, aku masih belum yakin kenapa aku terseret ke dalam ini...",
  ui_story_5062_50620101_81_dialog_content = "Haruskah saya katakan bahwa beberapa gaya yang disukai para komandan terlibat di sini? Pokoknya, ini adalah hal yang akan mereka lakukan.",
  ui_story_5062_50620101_82_dialog_content = "Para komandan akan mengevaluasi setiap keputusan yang dibuat oleh HQ Sementara.",
  ui_story_5062_50620101_83_dialog_content = "Setelah ini, saya akan merangkum evaluasi mereka dalam sebuah laporan dan mengirimkannya ke Ruang Intel.",
  ui_story_5062_50620101_84_dialog_content = "Ah, hampir saja aku lupa menyebutkan: Untuk sementara, urusan ini harus dirahasiakan dari Grand Marshal Wrath.",
  ui_story_5062_50620101_85_dialog_content = "Aku mengerti.",
  ui_story_5062_50620101_86_dialog_content = "Dan dengan itu, rekonstruksi Twilight resmi dimulai.",
  ui_story_5062_50620101_87_dialog_content = "Bisakah kamu membantu Grand Marshal dalam menunjuk personel?",
  ui_story_5062_50620101_88_dialog_content = "Atas nama Federasi Illumina dan warga Twilight, aku berterima kasih atas dukunganmu.",
  ui_story_5062_50620102_1_dialog_content = "PlayerName, maaf mengganggu, tapi kami membutuhkan bantuan Anda lagi untuk pekerjaan rekonstruksi hari ini.",
  ui_story_5062_50620102_2_dialog_content = "Tidak masalah sama sekali! Saya lebih dari baik-baik saja dengan itu.",
  ui_story_5062_50620102_3_dialog_content = "Rasanya luar biasa, menyaksikan kota ini dibangun kembali bata demi bata. Dan aku tahu bahwa setiap usaha yang kuberikan di sini benar-benar berharga.",
  ui_story_5062_50620102_4_dialog_content = "Jika kamu memiliki waktu, mari menuju ke Markas Sementara. Grand Marshal Wrath sedang menunggu kamu.",
  ui_story_5062_50620102_5_dialog_content = "Grand Marshal Wrath kembali? Aku ingat dia dipanggil kembali ke Illumina beberapa hari yang lalu...",
  ui_story_5062_50620102_6_dialog_content = "Jika ingin tahu lebih banyak tentang hal ini, Anda bisa menanyakannya langsung kepadanya.",
  ui_story_5062_50620102_7_dialog_content = "Hah, PlayerName, rupanya kau di sini.",
  ui_story_5062_50620102_8_dialog_content = "Petugas Vivian mengatakan bahwa kamu sedang mencari saya... Sepertinya ada beberapa komandan di sini juga...",
  ui_story_5062_50620102_9_dialog_content = "Hei! Hanya butuh beberapa hari kerja keras dan kamu sudah mulai menjadi lebih kuat.",
  ui_story_5062_50620102_10_dialog_content = "Terima kasih atas bantuanmu.",
  ui_story_5062_50620102_11_dialog_content = "Bagus.",
  ui_story_5062_50620102_12_dialog_content = "Mengenai penilaian ini... Komandan-komandan lain sudah memberitahuku tentang itu.",
  ui_story_5062_50620102_13_dialog_content = "Meskipun tak pernah terbayangkan aku akan melihat hari di mana kalian akan berdiri bersama Committee...",
  ui_story_5062_50620102_14_dialog_content = "Nah, seharusnya aku sudah mengantisipasinya. Ini adalah gayamu, para komandan.",
  ui_story_5062_50620102_15_dialog_content = "Hahahaha! Kamu benar-benar mulai terdengar semakin mirip Grand Marshal akhir-akhir ini.",
  ui_story_5062_50620102_16_dialog_content = "Maaf, tapi gelar Grand Marshal bukanlah lelucon. Kami tidak punya pilihan selain melakukan sedikit trik di sini.",
  ui_story_5062_50620102_17_dialog_content = "Meskipun begitu, performa Anda patut dicontoh.",
  ui_story_5062_50620102_18_dialog_content = "Itu sebagian besar berkat bantuan PlayerName.",
  ui_story_5062_50620102_19_dialog_content = "Memang, keahlian PlayerName dalam operasi pengiriman dan perintah sangat luar biasa.",
  ui_story_5062_50620102_20_dialog_content = "Namun, mengenal orang dengan baik dan memanfaatkan kemampuan mereka sebaik mungkin juga merupakan kualitas yang harus dimiliki oleh seorang Grand Marshal.",
  ui_story_5062_50620102_21_dialog_content = "Hah? Kenapa kalian semua menatapku seperti itu? Kalian benar-benar ingin aku juga berbagi pikiran...?",
  ui_story_5062_50620102_22_dialog_content = "Singkatnya, saya telah mengajukan evaluasi yang ditulis oleh semua komandan yang hadir dan diri saya sendiri kepada komando senior Federasi Illumina.",
  ui_story_5062_50620102_23_dialog_content = "Mengingat kinerja luar biasa yang ditunjukkan sepanjang misi ini, Grand Marshal Wrath akan dianugerahi Medali Illumina untuk Pengabdian Terkemuka.",
  ui_story_5062_50620102_24_dialog_content = "Selain itu, mengingat sifat ekstrem dari operasi Bantuan sebelumnya, penunjukan Grand Marshal Wrath saat itu hanya bersifat sementara.",
  ui_story_5062_50620102_25_dialog_content = "Oleh karena itu, kemungkinan besar akan diadakan upacara pelantikan resmi untuk Grand Marshal Wrath dalam waktu dekat.",
  ui_story_5062_50620102_26_dialog_content = "Upacara pelantikan... Hmm, sepertinya aku harus memikirkannya.",
  ui_story_5062_50620102_27_dialog_content = "(Memikirkan apa?)",
  ui_story_5062_50620102_28_dialog_content = "Setelah pengaturan spesifik selesai, aku akan memberi tahu semua orang mengenai waktu yang tepat.",
  ui_story_5062_50620102_29_dialog_content = "Lihat, sudah kubilang dia bisa melakukannya.",
  ui_story_5062_50620102_30_dialog_content = "Bukan itu yang kamu katakan di awal.",
  ui_story_5062_50620102_31_dialog_content = "Tak ada yang penting lagi—yang terpenting sekarang adalah memulihkan kota yang hancur akibat perang ini.",
  ui_story_5062_50620102_32_dialog_content = "Meskipun Komite telah mencapai kesimpulan, misi kita untuk membangun kembali Twilight belum selesai.",
  ui_story_5062_50620102_33_dialog_content = "Aku tidak akan beristirahat sampai Markas Sementara ini akhirnya selesai dibongkar.",
  ui_story_5062_50620102_34_dialog_content = "Kedengarannya benar.",
  ui_story_5062_50620102_35_dialog_content = "Aku akan berusaha sebaik mungkin untuk membantu semua orang juga.",
  ui_story_5062_50620102_36_dialog_content = "Hmm. Dengan kamu di sini, aku yakin kita bisa tenang.",
  ui_story_5062_50620102_37_dialog_content = "Tentu saja... Tunggu sebentar—maksudmu kamu bisa tenang dengan aku di sini?",
  ui_story_5062_50620102_38_dialog_content = "Penilaian telah selesai. Para komandan akan kembali ke Illumina setelah semua urusan tindak lanjut diatur.",
  ui_story_5062_50620102_39_dialog_content = "Ketidakhadiran kita akan meninggalkan lubang besar dalam pertahanan Illumina. Kita harus kembali.",
  ui_story_5062_50620102_40_dialog_content = "Jangan khawatir. Protokol yang telah kita tetapkan akan menjaga segalanya berjalan lancar.",
  ui_story_5062_50620102_41_dialog_content = "Terima kasih atas bantuan para relawan, bahkan setelah kalian semua pergi, rekonstruksi akan terus berlanjut tanpa hambatan.",
  ui_story_5062_50620102_42_dialog_content = "PlayerName, yang perlu kita lakukan adalah melanjutkan seperti biasa.",
  ui_story_5062_50620102_43_dialog_content = "Baiklah, Grand Marshal Wrath, kami akan pamit.",
  ui_story_5062_50620102_44_dialog_content = "Ayo! Tetap semangat, Nak!",
  ui_story_5062_50620102_45_dialog_content = "Sampai jumpa.",
  ui_story_5062_50620102_46_dialog_content = "Kami akan menunggu kamu di Illumina.",
  ui_story_5062_50620102_47_dialog_content = "PlayerName, ada hal lain yang ingin kubahas denganmu.",
  ui_story_5062_50620102_48_dialog_content = "Aku?",
  ui_story_5062_50620102_49_dialog_content = "Meskipun para komandan dan Komite memberikan evaluasi yang sangat positif untukku...",
  ui_story_5062_50620102_50_dialog_content = "Saya sangat menyadari bahwa semua ini tidak akan mungkin terjadi tanpa bantuan Anda.",
  ui_story_5062_50620102_51_dialog_content = "Maaf karena tidak bisa mengatur medali untukmu, tapi di sini—kamu bisa memiliki ini.",
  ui_story_5062_50620102_52_dialog_content = "Ini...",
  ui_story_5062_50620102_53_dialog_content = "Medali Illumina untuk Pengabdian Terkemuka. Umumnya, perhiasan ini hanya diberikan kepada perwira yang telah memberikan kontribusi luar biasa untuk Illumina.",
  ui_story_5062_50620102_54_dialog_content = "Maksud kamu yang disebutkan oleh Petugas Vivian tadi? Bukankah itu diberikan untuk kamu?",
  ui_story_5062_50620102_55_dialog_content = "Setengah dari ini milikmu... Mau aku belah?",
  ui_story_5062_50620102_56_dialog_content = "Tunggu! Tidak! Kamu nggak akan benar-benar melakukan itu pada sesuatu yang sangat berharga, 'kan?!",
  ui_story_5062_50620102_57_dialog_content = "Tunggu... Kenapa aku merasa kau tidak sedang main-main?",
  ui_story_5062_50620102_58_dialog_content = "Tentu saja bukan.",
  ui_story_5062_50620102_59_dialog_content = "Belum pernahkah kamu bermimpi menerima medali seperti ini?",
  ui_story_5062_50620102_60_dialog_content = "Tentu, tapi aku ingin medali yang benar-benar milikku—pengakuan sejati atas pencapaian yang telah kuperoleh.",
  ui_story_5062_50620102_61_option_content = "Mengenal orang dengan baik dan memanfaatkan kemampuan mereka sebaik mungkin juga layak mendapatkan medali!",
  ui_story_5062_50620102_62_dialog_content = "Commander Sharona baru saja mengatakan bahwa mengenal orang dengan baik dan memanfaatkan kemampuan mereka sebaik mungkin adalah kualitas yang harus dimiliki oleh seorang Grand Marshal.",
  ui_story_5062_50620102_63_dialog_content = "Menempatkan saya dalam posisi yang memaksimalkan bakat saya juga merupakan tanda keahlian yang sebenarnya.",
  ui_story_5062_50620102_64_option_content = "Tapi meskipun begitu, jangan membelahnya jadi dua!",
  ui_story_5062_50620102_65_dialog_content = "Ini adalah medali yang diberikan kepada petugas Illumina. Tidak pantas bagi saya untuk mengambilnya.",
  ui_story_5062_50620102_66_dialog_content = "Selain itu, saya hanya ingin membantu membangun kembali Twilight. Tidak terlalu peduli dengan medali.",
  ui_story_5062_50620102_67_dialog_content = "Ini medali milik kamu. Tolong jaga dengan baik.",
  ui_story_5062_50620102_68_dialog_content = "Meskipun apa yang Anda katakan tadi benar, itu hanya sebagian alasan mengapa medali ini sangat berharga.",
  ui_story_5062_50620102_69_dialog_content = "Bahkan perwira senior hanya mendapat beberapa kesempatan untuk menerima medali ini seumur hidup mereka.",
  ui_story_5062_50620102_70_dialog_content = "Juga... Dulu aku sering bermimpi untuk mendapatkan salah satu dari ini.",
  ui_story_5062_50620102_71_dialog_content = "Lalu kenapa...",
  ui_story_5062_50620102_72_dialog_content = "Kenapa menurutmu mereka memberiku medali ini?",
  ui_story_5062_50620102_73_dialog_content = "Tentu saja, untuk apa yang telah Anda lakukan untuk Twilight.",
  ui_story_5062_50620102_74_dialog_content = "Twilight tidak begitu penting bagi mereka, dan tugas rekonstruksi ini hanyalah alasan untuk mengamati saya dalam aksi.",
  ui_story_5062_50620102_75_dialog_content = "Untuk medali ini... ini hanyalah mainan, diberikan kepada tikus lab karena patuh pada aturan sekali lagi.",
  ui_story_5062_50620102_76_dialog_content = "Membuatku marah melihat simbol kehormatan yang hebat ini digunakan untuk menjilat seseorang seolah-olah itu tidak berarti apa-apa.",
  ui_story_5062_50620102_77_dialog_content = "Wrath...",
  ui_story_5062_50620102_78_dialog_content = "Aku takkan menggigit lidahku dan menjadi tikus percobaan mereka lagi.",
  ui_story_5062_50620102_79_dialog_content = "Tapi, baik menangani proyek rekonstruksi ini atau berurusan dengan orang-orang penting, saya masih memiliki banyak hal yang harus dikerjakan.",
  ui_story_5062_50620102_80_dialog_content = "Bagaimana jika kamu menganggap medali ini sebagai hadiah ucapan terima kasih dari orang-orang Twilight?",
  ui_story_5062_50620102_81_dialog_content = "Lupakan saja tugas itu. Membangun kembali Twilight, itu sendiri, adalah suatu pencapaian yang akan mengubah kehidupan penduduk setempat.",
  ui_story_5062_50620102_82_dialog_content = "Bahkan jika aku hampir menjadi gila dan menghancurkan tempat ini?",
  ui_story_5062_50620102_83_dialog_content = "Itu bukan salahmu.",
  ui_story_5062_50620102_84_dialog_content = "Aku tahu... Hanya bercanda.",
  ui_story_5062_50620102_85_dialog_content = "Baiklah, aku akan menyimpannya sebagai kenang-kenangan. Tapi lain kali, aku akan mendapatkan medali untuk keberhasilanku di medan perang dan menerimanya dengan integritas.",
  ui_story_5062_50620102_86_dialog_content = "Sebelum itu, kita perlu menyelesaikan tugas yang ada di tangan kita.",
  ui_story_5062_50620102_87_dialog_content = "Kamu benar. Aku siap untuk memulai pekerjaan hari ini.",
  ui_story_5062_50620102_88_dialog_content = "Ayo, PlayerName. Mari pergi jalan-jalan sebentar sebelum bekerja.",
  ui_story_5062_50620102_89_dialog_content = "Berjalanlah bersamaku, Caelestite. Mari kita lihat Twilight yang telah kita bantu bangun kembali.",
  ui_story_5062_50620103_1_dialog_content = "Ini Wrath di sini. Tolong balas jika kamu bisa mendengarku.",
  ui_story_5062_50620103_2_dialog_content = "Roger. Ini adalah Gram.",
  ui_story_5062_50620103_3_dialog_content = "Laporkan situasi saat ini.",
  ui_story_5062_50620103_4_dialog_content = "Di perimeter area misi, bersiap untuk masuk.",
  ui_story_5062_50620103_5_dialog_content = "Komunikasi lancar, dan suplai cukup. Sejauh ini, semuanya baik-baik saja... kecuali...",
  ui_story_5062_50620103_6_dialog_content = "Kecuali apa?",
  ui_story_5062_50620103_7_dialog_content = "Kecuali Benny dan Revy yang terus-menerus bersaing satu sama lain untuk mendapatkan kesempatan bertarung melawan beberapa Eclipsite.",
  ui_story_5062_50620103_8_dialog_content = "Mereka adalah petarung yang sangat baik dalam hal bakat individu dan pilihan yang ideal untuk misi eksplorasi skala kecil seperti ini.",
  ui_story_5062_50620103_9_dialog_content = "Tapi petugas intelijen kami mengklaim bahwa mereka sangat berisik sehingga dia bahkan tidak bisa tidur nyenyak di malam hari!",
  ui_story_5062_50620103_10_dialog_content = "Hmm... Kalau soal mengelola intel, tidak ada yang bisa menandingi dia.",
  ui_story_5062_50620103_11_dialog_content = "Oh ya, dan sepertinya ada sesuatu yang aneh mengambang di sekitar Chandra.",
  ui_story_5062_50620103_12_dialog_content = "Lingkungan operasi ini sangat khusus. Oleh karena itu, konseling psikologis sangat penting bagi personel tempur.",
  ui_story_5062_50620103_13_dialog_content = "Untuk masalah lainnya, mereka bisa diabaikan untuk sementara ini.",
  ui_story_5062_50620103_14_dialog_content = "Roger. Jadi semua hal baik-baik saja.",
  ui_story_5062_50620103_15_dialog_content = "Oke. Sekarang biar kujelaskan misimu sekali lagi.",
  ui_story_5062_50620103_16_dialog_content = "Kali ini, Anda akan memulai dari Twilight, melanjutkan untuk menjelajahi perbatasan malam abadi.",
  ui_story_5062_50620103_17_dialog_content = "Kita harus memantau aktivitas Eclipsite seketat mungkin untuk mencegah serangan mendadak lainnya.",
  ui_story_5062_50620103_18_dialog_content = "Aku mengerti.",
  ui_story_5062_50620103_19_dialog_content = "Nanti aku akan menyinkronkan koordinat lokasi eksplorasi rencana ini dengan kamu.",
  ui_story_5062_50620103_20_dialog_content = "Untuk kejadian yang tidak direncanakan, Anda harus mengandalkan pengalaman dan menyesuaikan diri dengan situasi yang ada.",
  ui_story_5062_50620103_21_dialog_content = "Berfikir cepat—jenis favorit saya.",
  ui_story_5062_50620103_22_dialog_content = "Jangan lupa, ini adalah misi penjelajahan. Lakukan saja tugas pengintaianmu.",
  ui_story_5062_50620103_23_dialog_content = "Jadi, jika kita bertemu musuh, kita harus menunda keberanian untuk hari lain dan segera mundur, ya?",
  ui_story_5062_50620103_24_dialog_content = "Ya. Saya yakin kamu akan mampu menangani situasi apa pun yang dihadapi.",
  ui_story_5062_50620103_25_dialog_content = "Apa?! Mundur?! Kenapa kita tidak saja meledakkan mereka semua menjadi debu! Duar!",
  ui_story_5062_50620103_26_dialog_content = "Cukup... Masih ingat tujuan misi kita? Kita seharusnya tidak—",
  ui_story_5062_50620103_27_dialog_content = "Bagaimana kalau kita bertaruh? Ayo lihat siapa yang bisa mengalahkan lebih banyak Eclipsite! Gimana menurutmu?!",
  ui_story_5062_50620103_28_dialog_content = "Hei! Jangan asal mengayunkan senjatamu begitu saja!",
  ui_story_5062_50620103_29_dialog_content = "Kamu siap! Curo, hitung untukku, ya?",
  ui_story_5062_50620103_30_dialog_content = "Maaf, Kapten, aku akan menahan keduanya...",
  ui_story_5062_50620103_31_dialog_content = "Izinkan saya membantu!",
  ui_story_5062_50620103_32_dialog_content = "Benny, jangan sentuh tas itu! Itu adalah jatah kita!",
  ui_story_5062_50620103_33_dialog_content = "Hmm? Apakah aku mendengar seseorang bilang \"jatah,\" meong?",
  ui_story_5062_50620103_34_dialog_content = "Ikan kering! Ikan kering!",
  ui_story_5062_50620103_35_dialog_content = "Tidak ada ikan kering di sini! Ransum tempur harus tinggi kalori. Semua yang kamu lihat di sini disiapkan oleh saya sendiri.",
  ui_story_5062_50620103_36_dialog_content = "Bau ini... Bau ini! Meong... Jangan-jangan...?",
  ui_story_5062_50620103_37_dialog_content = "Sepertinya ini adalah produk keju jenis tertentu.",
  ui_story_5062_50620103_38_dialog_content = "Keju! Aww, kenapa harus keju?! Meong!",
  ui_story_5062_50620103_39_dialog_content = "Philyshy, tolong jangan buang-buang suplai kita!",
  ui_story_5062_50620103_40_dialog_content = "Ini adalah tim yang sangat enerjik! Ini mengingatkan saya pada hari-hari bersama Stone Force.",
  ui_story_5062_50620103_41_dialog_content = "Dulu, aku persis seperti mereka sekarang... Hmm, apa ya kata yang tepat... itu dia—liar!",
  ui_story_5062_50620103_42_dialog_content = "Jaga kontak secara teratur setiap jam dan laporkan saat tiba di titik target atau jika ada situasi lain yang muncul.",
  ui_story_5062_50620103_43_dialog_content = "Baiklah, kita sudah melalui semua ini dengan cukup baik sebelum misi.",
  ui_story_5062_50620103_44_dialog_content = "Kita hampir tidak tahu apa yang mungkin menunggu kita di luar garis pertahanan. Tetap waspada.",
  ui_story_5062_50620103_45_dialog_content = "Mengerti. Aku hanya berharap kita bisa menyelesaikan ini daripada kamu terus bicara tanpa henti...",
  ui_story_5062_50620103_46_dialog_content = "Aku akan berusaha sebaik mungkin untuk menghentikan kebiasaan lamaku... Aku tak akan membiarkan apa yang terjadi dulu terulang lagi.",
  ui_story_5062_50620103_47_dialog_content = "Maaf menugaskan kamu dalam misi ini. Ini agak improvisasi.",
  ui_story_5062_50620103_48_dialog_content = "Sedikit orang yang cukup kompeten untuk dikirim ke perbatasan. Aku memang tidak punya banyak pilihan.",
  ui_story_5062_50620103_49_dialog_content = "Tidak apa-apa. Aku prajurit. Medan tempur adalah rumahku.",
  ui_story_5062_50620103_50_dialog_content = "Cukup untuk obrolan. Dilihat dari cahaya yang semakin redup di sekitar, saya rasa kita sudah memasuki area misi.",
  ui_story_5062_50620103_51_dialog_content = "Awasi erat pergerakan di sekitarmu. Aku akan menyinkronkan koordinat titik target pertama denganmu.",
  ui_story_5062_50620103_52_dialog_content = "Aku mengerti.",
  ui_story_5062_50620103_53_dialog_content = "Nona Perwira Intelijen, tolong konfirmasi intelijen Anda mengenai titik target.",
  ui_story_5062_50620103_54_dialog_content = "Kenapa kita masih harus bekerja saat kita bahkan tidak punya ikan kering, meong...?",
  ui_story_5062_50620103_55_dialog_content = "Sudah melihat lokasi target. Siap untuk memulai misi eksplorasi.",
  ui_story_5062_50620103_56_dialog_content = "Kita sudah di sini? Biar aku yang memimpin ya!",
  ui_story_5062_50620103_57_dialog_content = "Apa?! Kalau ada yang jadi kapten, harusnya aku! Bagaimana kalau kita bertarung untuk menentukannya?",
  ui_story_5062_50620103_58_dialog_content = "Tentu saja, Tuan Gram adalah kapten... Curo, tidak bisakah kamu menghentikan mereka?",
  ui_story_5062_50620103_59_dialog_content = "Aku tidak ada hubungannya dengan orang-orang bodoh itu...",
  ui_story_5062_50620103_60_dialog_content = "Gram, ada satu hal lagi.",
  ui_story_5062_50620103_61_dialog_content = "Lanjutkan, Grand Marshal.",
  ui_story_5062_50620103_62_dialog_content = "... Menjadi kapten skuad ini bukanlah pekerjaan yang mudah. Terima kasih."
}
return config
